const URL='https://azastzjxnzjaloxmnbfd.supabase.co',KEY='sb_publishable_BPYP79Lh70nWiwxExhRBvw_dRgVsed7';let token=null,uid=null,admin=false,demo=true,page='dashboard';const $=id=>document.getElementById(id),modal=$('modal'),money=n=>Number(n||0).toLocaleString('fa-IR'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const teacherData=[['اکبری','ویولن، ترومپت، آهنگسازی و تنظیم'],['کرمی','دف، کاخن، موسیقی کودک'],['هوشیانی','دف، کاخن، جیمبی، هنگ درام'],['حاجیان','گیتار، سلفژ، صداسازی، تئوری موسیقی'],['علیرضایی','تنبک'],['فروقی','پیانو، درام، کیبورد'],['رضایی','سنتور'],['جعفری','تار، سه تار، عود'],['محسن اکبری','نی، آواز، کلارینت، ترومپت'],['سلیمانی','گیتار فلامنکو'],['ریاحی','فیلم برداری و عکاسی، فوتوشاپ، آب رنگ'],['سمیه سلیمانی','سیاه قلم، نقاشی کودک'],['پوربختگان','دی جی']];
