const days=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];const menu=[['dashboard','◫','نمای کلی'],['students','♧','هنرجویان'],['schedule','▦','تقویم کلاس‌ها'],['payments','▤','شهریه و پرداخت‌ها'],['expenses','◈','هزینه‌های آموزشگاه'],['teachers','♬','اساتید و دستمزد'],['requests','◷','غیبت و جبرانی'],['import','⇥','انتقال اطلاعات'],['rules','☷','قوانین آموزشگاه'],['portal','◎','پنل هنرجو']];
async function api(path,method='GET',body){const r=await fetch(URL+path,{method,headers:{apikey:KEY,Authorization:'Bearer '+(token||KEY),'Content-Type':'application/json',Prefer:'return=representation'},body:body?JSON.stringify(body):undefined});const data=await r.json().catch(()=>null);if(!r.ok)throw Error(data?.message||data?.error_description||'خطا در ارتباط با سرور');return data;}
async function reload(){for(const t of ['teachers','students','payments','sessions','notices','absence_requests',...(admin?['expenses','payroll']:[])]) db[t]=await api('/rest/v1/'+t+'?select=*');if(!admin)db.expenses=[];render();}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4500)}
function allowed(){if(demo||!admin){toast(demo?'برای ثبت اطلاعات واقعی ابتدا وارد حساب مدیریت شوید.':'دسترسی مدیریت لازم است.');return false}return true}
const teacher=id=>db.teachers.find(t=>t.id===id)?.name||'—',full=s=>s.first_name+' '+s.last_name,credit=s=>s.opening_credit+db.payments.filter(p=>p.student_id===s.id).reduce((a,p)=>a+p.terms*4,0)-db.sessions.filter(c=>c.student_id===s.id&&['completed','absent'].includes(c.status)).length;
function eligible(s){return credit(s)>0&&!Number(s.opening_debt)}
function tag(s){return `<span class="badge ${eligible(s)?'':'red'}">${eligible(s)?'مجاز به حضور':'نیازمند پرداخت'}</span>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">هنوز اطلاعاتی ثبت نشده است</td></tr>`}</tbody></table></div>`}
function title(name,sub,action=''){return `<div class="title"><div><h1>${name}</h1><div class="sub">${sub}</div></div>${action}</div>`}function btn(s,f){return `<button class="primary" onclick="${f}">＋ ${s}</button>`}
function go(p){page=p;render()}
function render(){const visible=demo||admin?menu:menu.filter(m=>['portal','rules','requests'].includes(m[0]));$('nav').innerHTML=visible.map(([id,icon,label])=>`<button class="${page===id?'active':''}" onclick="go('${id}')"><em>${icon}</em>${label}</button>`).join('');$('crumb').textContent=menu.find(m=>m[0]===page)?.[2]||'';$('content').innerHTML=views[page]();}
const views={dashboard(){const income=db.payments.reduce((a,p)=>a+Number(p.amount),0),out=db.expenses.reduce((a,p)=>a+Number(p.amount),0),salaries=db.sessions.reduce((a,s)=>a+Number(s.teacher_share||0),0);return title('هنر، با نظم زیباتر می‌شود.','یک نگاه به جریان امروز آموزشگاه',btn('ثبت هنرجوی جدید','newStudent()'))+`<div class="hero"><div><h2>به آوای هزاردستان خوش آمدید</h2><p>همه‌چیز برای یک روز هماهنگ؛ از اولین نت تا آخرین کلاس.</p></div><span class="note">♫</span></div><div class="stats">${[['هنرجویان',db.students.length,'هنرجوی ثبت‌شده'],['شهریه دریافتی',income,'تومان · پرداخت‌های ثبت‌شده'],['هزینه و دستمزد',out+salaries,'تومان · هزینه‌ها + جلسات برگزارشده'],['مانده عملیاتی',income-out-salaries,'تومان · دریافت منهای هزینه و دستمزد']].map(([s,n,f])=>`<div class="card"><div class="statlabel">${s}<span>◈</span></div><div class="statnum">${money(n)}</div><div class="statfoot">${f}</div></div>`).join('')}</div><div class="grid"><div class="card"><div class="cardhead"><h3>جریان مالی آموزشگاه</h3><span class="sub">${demo?'نمودار نمونه':'شش ماه اخیر'}</span></div><div class="chart">${Array.from({length:6},(_,i)=>{const date=new Date();date.setMonth(date.getMonth()-5+i);const filter=a=>a.filter(p=>new Date(p.created_at||p.expense_date).getMonth()===date.getMonth()&&new Date(p.created_at||p.expense_date).getFullYear()===date.getFullYear()).reduce((s,p)=>s+Number(p.amount),0);const amounts=[filter(db.payments),filter(db.expenses)];return `<div class="bars"><div class="bar" style="height:${demo?[40,65,48,80,61,92][i]:Math.min(95,amounts[0]/200000)}%"></div><div class="bar light" style="height:${demo?[22,32,28,40,33,45][i]:Math.min(95,amounts[1]/200000)}%"></div><label>${date.toLocaleDateString('fa-IR',{month:'short'})}</label></div>`}).join('')}</div><div class="legend"><span><i class="dot"></i>شهریه دریافتی</span><span><i class="dot" style="background:#d9e5dc"></i>هزینه‌های ثبت‌شده</span></div></div><div class="card"><div class="cardhead"><h3>نبض آموزشگاه</h3><span>◉</span></div><div class="row"><span>نیازمند تمدید شهریه</span><b>${money(db.students.filter(s=>!eligible(s)).length)} نفر</b></div><div class="row"><span>درخواست غیبت در انتظار</span><b>${money(db.absence_requests.filter(r=>r.status==='pending').length)}</b></div><div class="row"><span>کلاس‌های برگزارشده</span><b>${money(db.sessions.filter(s=>s.status==='completed').length)}</b></div><div class="row"><span>اساتید آموزشگاه</span><b>${money(db.teachers.length)} استاد</b></div><p class="sub">۲۰ دقیقه کلاس · ۴ جلسه در هر ترم</p></div></div><div class="card" style="margin-top:22px"><div class="cardhead"><h3>هنرجویان و وضعیت حضور</h3><a onclick="go('students')">مشاهده همه ←</a></div>${studentTable(db.students.slice(0,5))}</div>`},
students(){return title('هنرجویان','پرونده، زمان ثابت و وضعیت شهریه',btn('هنرجوی جدید','newStudent()'))+`<div class="card"><div class="toolbar"><input placeholder="جست‌وجوی نام یا شماره موبایل…" oninput="filterStudents(this.value)"></div><div id="studentlist">${studentTable(db.students)}</div></div>`},
teachers(){return title('اساتید آموزشگاه','سهم استاد: ۶۰٪ هر جلسه برگزارشده؛ ۳۰۰٬۰۰۰ تومان',btn('ثبت تسویه استاد','newPayroll()'))+`<div class="teachergrid">${db.teachers.map(t=>{let sessions=db.sessions.filter(c=>c.status==='completed'&&db.students.find(s=>s.id===c.student_id)?.teacher_id===t.id);return `<div class="card"><div class="avatar">♫</div><h3>استاد ${esc(t.name)}</h3><p>${esc(t.subjects.join(' · '))}</p><div class="row"><span>جلسات برگزارشده</span><b>${money(sessions.length)}</b></div><div class="row"><span>دستمزد محاسبه‌شده</span><b>${money(sessions.reduce((a,c)=>a+Number(c.teacher_share),0))} تومان</b></div><div class="row"><span>تسویه ثبت‌شده</span><b>${money((db.payroll||[]).filter(p=>p.teacher_id===t.id).reduce((a,p)=>a+Number(p.amount),0))} تومان</b></div></div>`}).join('')}</div>`},
payments(){return title('شهریه و پرداخت‌ها','یک ترم ۲٬۰۰۰٬۰۰۰ تومان · دو ترم ۴٬۰۰۰٬۰۰۰ تومان',btn('ثبت دریافت شهریه','newPayment()'))+`<div class="card">${table(['هنرجو','تعداد ترم','مبلغ / تومان','شماره پیگیری','تاریخ'],db.payments.map(p=>`<tr><td>${esc(full(db.students.find(s=>s.id===p.student_id)||{first_name:'',last_name:''}))}</td><td>${money(p.terms)}</td><td>${money(p.amount)}</td><td>${esc(p.reference)}</td><td>${new Date(p.created_at).toLocaleDateString('fa-IR')}</td></tr>`))}</div><p class="sub">ثبت دریافت فقط توسط مدیر پس از بررسی واریز انجام می‌شود. درگاه آنلاین هنوز متصل نیست.</p>`},
expenses(){return title('هزینه‌های آموزشگاه','اجاره، قبوض و خریدها؛ همه در یک دفتر',btn('ثبت هزینه','newExpense()'))+`<div class="card">${table(['دسته‌بندی','شرح هزینه','مبلغ / تومان','تاریخ'],db.expenses.map(p=>`<tr><td>${esc(p.category)}</td><td>${esc(p.description)}</td><td>${money(p.amount)}</td><td>${new Date(p.expense_date).toLocaleDateString('fa-IR')}</td></tr>`))}</div>`},
schedule(){return title('تقویم کلاس‌ها','زمان هنرجو ثابت است؛ هر جلسه ۲۰ دقیقه',btn('ایجاد ۴ جلسه ترم','generateTerm()'))+`<div class="card"><div class="toolbar"><button onclick="showProgram()">برنامه رشته‌ها در هفته</button></div>${table(['هنرجو','استاد','زمان','وضعیت','عملیات'],db.sessions.sort((a,b)=>a.starts_at.localeCompare(b.starts_at)).map(c=>{const s=db.students.find(s=>s.id===c.student_id);return `<tr><td>${esc(s?full(s):'—')}</td><td>${esc(s?teacher(s.teacher_id):'—')}</td><td>${new Date(c.starts_at).toLocaleString('fa-IR',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tehran'})}</td><td>${esc(statusLabel(c.status))}</td><td>${c.status==='scheduled'&&admin?`<button onclick="finishSession('${c.id}','completed')">ثبت حضور</button> <button onclick="finishSession('${c.id}','absent')">غیبت</button> <button onclick="cancelTeacher('${c.id}')">لغو استاد</button>`:''}${c.status==='teacher_cancelled'&&admin?`<button onclick="makeup('${c.id}')">تعیین جبرانی</button>`:''}</td></tr>`}))}</div>`},
requests(){return title('غیبت و کلاس جبرانی','اعلام حداقل ۴ روز قبل؛ یک غیبت مجاز برای هر پرداخت دو ترم',btn('درخواست غیبت','requestAbsence()'))+`<div class="card">${table(['هنرجو','وضعیت درخواست','عملیات'],db.absence_requests.map(r=>`<tr><td>${esc(full(db.students.find(s=>s.id===r.student_id)||{first_name:'',last_name:''}))}</td><td>${esc(({pending:'در انتظار',approved:'تأییدشده',rejected:'ردشده'})[r.status])}</td><td>${admin&&r.status==='pending'?`<button onclick="approveAbsence('${r.id}')">تأیید و حفظ اعتبار جلسه</button>`:'—'}</td></tr>`))}</div>`},
portal(){let s=db.students[0];return title('پرتال هنرجو','شهریه، اعتبار جلسات و اطلاعیه‌های شما')+(s?`<div class="hero"><div><h2>${esc(full(s))}، به پرتال خودت خوش آمدی</h2><p>${esc(s.subject)} · استاد ${esc(teacher(s.teacher_id))} · ${days[s.weekday]} ساعت ${esc(s.class_time.slice(0,5))}</p></div><span class="note">♫</span></div><div class="stats">${[['پرداخت ثبت‌شده',money(db.payments.filter(p=>p.student_id===s.id).reduce((a,p)=>a+Number(p.amount),0))+' تومان'],['جلسات باقی‌مانده',money(credit(s))+' جلسه'],['بدهی انتقالی',money(s.opening_debt)+' تومان'],['وضعیت شرکت در کلاس',eligible(s)?'مجاز به حضور':'پرداخت الزامی']].map(a=>`<div class="card"><div class="sub">${a[0]}</div><h3>${a[1]}</h3></div>`).join('')}</div><div class="card"><h3>اطلاعیه‌های من</h3>${db.notices.filter(n=>!n.student_id||n.student_id===s.id).map(n=>`<div class="row">${esc(n.message)}</div>`).join('')||'<p class="sub">اطلاعیه‌ای ثبت نشده است</p>'}<p>برای پرداخت شهریه با دفتر هماهنگ کنید؛ اعتبار پس از تأیید واریز اضافه می‌شود.</p><button onclick="go('payments')">سوابق پرداخت</button> <button onclick="requestAbsence()">اعلام غیبت</button></div>`:'<div class="card empty">پرونده هنرجو هنوز به حساب شما متصل نشده است. با مدیر آموزشگاه هماهنگ کنید.</div>')},
import(){return title('شروع منظم، بدون از دست دادن سابقه','پروتکل انتقال هنرجویان فعلی به سامانه')+`<div class="card policy"><h3>۱. یک تاریخ شروع مشخص کنید</h3><p>جلسات قبل از تاریخ شروع را دوباره صورتحساب نکنید. برای هر هنرجو فقط اعتبار باقی‌مانده و بدهی قطعی را وارد کنید.</p><h3>۲. اطلاعات را از دفتر آموزشگاه تطبیق دهید</h3><p>نام و نام خانوادگی، نام پدر، کد ملی، موبایل، تاریخ تولد میلادی، تلفن و آدرس منزل، استاد، رشته، روز و ساعت ثابت، جلسات باقی‌مانده و بدهی انتقالی.</p><h3>۳. ابتدا پیش‌بررسی، سپس ثبت</h3><p>قالب JSON را دریافت و تکمیل کنید. پیش‌بررسی، کد ملی و تداخل استاد/زمان را کنترل می‌کند. ثبت نهایی گروهی است و در صورت خطا هیچ ردیفی ثبت نمی‌شود.</p><button onclick="downloadTemplate()">دریافت قالب انتقال JSON</button> <button onclick="document.getElementById('importfile').click()">انتخاب و پیش‌بررسی فایل</button><input id="importfile" type="file" accept="application/json" hidden onchange="previewImport(this)"><div id="importpreview"></div><h3>۴. اتصال حساب هنرجو</h3><p>پس از ساخت حساب در Supabase Auth، شناسه حساب را در پرونده هنرجو درج کنید. حساب مدیر باید در جدول academy_staff با نقش admin تعریف شود. هیچ حسابی خودکار مدیر نمی‌شود.</p><h3>۵. تأیید نهایی</h3><p>هنرجو مانده اعتبار و بدهی را تأیید کند؛ سپس جلسات آتی ایجاد شوند. پرداخت‌های قدیمی که در اعتبار انتقالی حساب شده‌اند دوباره ثبت نشوند.</p></div>`},
rules(){return title('قوانین و مقررات','نسخه اصلی به همراه استثنای اعلام‌شده مدیریت')+`<div class="grid"><div class="card policy">${[['حضور منظم','حضور به‌موقع در تمام جلسات الزامی است. هنرجو حداقل ۱۰ دقیقه قبل از شروع کلاس در آموزشگاه حاضر باشد. تأخیر قابل جبران نیست.'],['غیبت','غیبت بدون هماهنگی قبلی سوخت می‌شود؛ هزینه قابل استرداد نیست. در موارد خاص و اضطراری تصمیم با مدیریت است. استثنا: پرداخت هم‌زمان دو ترم، یک غیبت مجاز با اعلام حداقل ۴ روز قبل.'],['انضباط','احترام به اساتید، کارکنان و سایر هنرجویان، رعایت شئونات اخلاقی و فرهنگی الزامی است. سروصدا و بی‌نظمی ممنوع است.'],['حفظ اموال','مراقبت از سازها و تجهیزات الزامی است؛ خسارت ناشی از بی‌احتیاطی یا استفاده نادرست بر عهده هنرجو است.'],['شهریه','پرداخت پیش از شروع دوره الزامی است. پس از ثبت‌نام و آغاز کلاس شهریه قابل استرداد نیست.'],['تعطیلی کلاس‌ها','تعطیلات رسمی طبق برنامه اعلام‌شده برگزار یا جابه‌جا می‌شود. تغییر زمان فقط از سوی مدیریت اعلام می‌شود. غیبت استاد با کلاس جبرانی و حفظ اعتبار هنرجو پیگیری می‌شود.'],['تلفن همراه','استفاده در کلاس ممنوع، مگر با اجازه مدرس؛ تلفن در حالت سکوت باشد.'],['ضبط صدا و تصویر','فیلم‌برداری، عکاسی یا ضبط صدا بدون اجازه مدرس و مدیریت ممنوع است.'],['وسایل شخصی','آموزشگاه مسئول مفقودی یا آسیب وسایل شخصی نیست.'],['اطلاع‌رسانی','اطلاعیه‌ها از طریق تماس، پیامک یا شبکه‌های اجتماعی رسمی است؛ هنرجو موظف به پیگیری است.'],['حق تصمیم‌گیری','تصمیم نهایی موارد پیش‌بینی‌نشده بر عهده مدیریت آموزشگاه است.']].map((a,i)=>`<h3>${money(i+1)}. ${a[0]}</h3><p>${a[1]}</p>`).join('')}</div><div><img class="image" src="rules.webp" alt="متن اصلی قوانین آموزشگاه"><p class="sub">تصویر اصلی قوانین ارسالی آموزشگاه</p><button onclick="acceptRules()">قوانین را خوانده‌ام و می‌پذیرم</button></div></div>`}}
function studentTable(list){return table(['هنرجو','رشته و استاد','زمان ثابت','اعتبار','وضعیت','پرونده'],list.map(s=>`<tr><td><b>${esc(full(s))}</b></td><td>${esc(s.subject)} <span class="sub">· ${esc(teacher(s.teacher_id))}</span></td><td>${days[s.weekday]} ${esc(s.class_time?.slice(0,5))}</td><td>${money(credit(s))} جلسه</td><td>${tag(s)}</td><td><button onclick="studentDetail('${s.id}')">مشاهده</button></td></tr>`))}function filterStudents(q){$('studentlist').innerHTML=studentTable(db.students.filter(s=>(full(s)+(s.mobile||'')).includes(q)))}
function field(name,label,type='text',options=null){return {name,label,type,options}}
function form(title,fields,submit){$('mtitle').textContent=title;$('error').textContent='';$('fields').innerHTML=fields.map(f=>`<label>${esc(f.label)}${f.options?`<select name="${f.name}" required>${f.options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select>`:`<input name="${f.name}" type="${f.type}" required ${f.type==='number'?'min="0" step="1"':''}>`}</label>`).join('');$('form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));await submit(data);modal.close();toast('اطلاعات ثبت شد');await reload()}catch(e){$('error').textContent=e.message}};modal.showModal()}
const studentsOpt=()=>db.students.map(s=>[s.id,full(s)]);
function login(){form('ورود امن به حساب',[field('email','ایمیل حساب','email'),field('password','رمز عبور','password')],async d=>{const a=await api('/auth/v1/token?grant_type=password','POST',d);token=a.access_token;uid=a.user.id;const staff=await api('/rest/v1/academy_staff?select=role&user_id=eq.'+uid);admin=staff.some(s=>s.role==='admin');demo=false;page=admin?'dashboard':'portal';$('notice').textContent=admin?'متصل به پایگاه داده واقعی · حساب مدیریت':'متصل به پرتال شخصی هنرجو';$('loginbtn').textContent='خروج';$('loginbtn').onclick=()=>location.reload()})}
function newStudent(){if(!allowed())return;form('ثبت هنرجو و مانده افتتاحیه',[field('first_name','نام'),field('last_name','نام خانوادگی'),field('father_name','نام پدر'),field('national_id','کد ملی ۱۰ رقمی'),field('mobile','موبایل','tel'),field('birth_date','تاریخ تولد (میلادی)','date'),field('home_phone','تلفن منزل','tel'),field('address','آدرس منزل'),field('teacher_id','استاد','text',db.teachers.map(t=>[t.id,t.name])),field('subject','رشته'),field('weekday','روز ثابت','text',days.map((d,i)=>[i,d])),field('class_time','ساعت ثابت','time'),field('opening_credit','جلسات باقی‌مانده قبلی','number'),field('opening_debt','بدهی قبلی / تومان','number')],async d=>{validateStudent(d);await api('/rest/v1/students','POST',d)})}
function validateStudent(s){if(!/^\d{10}$/.test(s.national_id))throw Error('کد ملی باید ۱۰ رقم انگلیسی باشد');if(!/^09\d{9}$/.test(s.mobile))throw Error('موبایل باید ۱۱ رقم و با 09 شروع شود');const t=db.teachers.find(t=>t.id===s.teacher_id);if(!t?.subjects.includes(s.subject))throw Error('رشته با فهرست رشته‌های استاد مطابقت ندارد');if(db.students.some(x=>x.teacher_id===s.teacher_id&&Number(x.weekday)===Number(s.weekday)&&Math.abs((Number(x.class_time.slice(0,2))*60+Number(x.class_time.slice(3,5)))-(Number(s.class_time.slice(0,2))*60+Number(s.class_time.slice(3,5))))<20))throw Error('این زمان با کلاس دیگری تداخل دارد')}
function studentDetail(id){const s=db.students.find(s=>s.id===id);if(!admin){toast('برای مشاهده پرونده واقعی وارد شوید');return}form('اتصال حساب و تسویه بدهی انتقالی',[field('user_id','شناسه حساب Supabase Auth (UUID)'),field('opening_debt','مانده بدهی انتقالی / تومان','number')],async d=>{await api('/rest/v1/students?id=eq.'+id,'PATCH',d)});$('form').elements.opening_debt.value=s.opening_debt}
function newPayment(){if(!allowed())return;form('ثبت دریافت قطعی شهریه',[field('student_id','هنرجو','text',studentsOpt()),field('terms','تعداد ترم','text',[[1,'یک ترم · ۲ میلیون تومان'],[2,'دو ترم · ۴ میلیون تومان']]),field('reference','شماره پیگیری یکتا')],d=>api('/rest/v1/payments','POST',{...d,amount:Number(d.terms)*2000000}))}
function newExpense(){if(!allowed())return;form('ثبت هزینه آموزشگاه',[field('category','دسته','text',['اجاره','آب','برق','گاز','خرید متفرقه','سایر'].map(x=>[x,x])),field('description','شرح هزینه'),field('amount','مبلغ / تومان','number'),field('expense_date','تاریخ','date')],d=>{if(Number(d.amount)<=0)throw Error('مبلغ باید مثبت باشد');return api('/rest/v1/expenses','POST',d)})}
function statusLabel(s){return ({scheduled:'برنامه‌ریزی شده',completed:'برگزار شده',absent:'غیبت غیرمجاز',teacher_cancelled:'لغو توسط استاد',excused:'غیبت مجاز'})[s]}
function generateTerm(){if(!allowed())return;form('ایجاد ۴ جلسه هفتگی',[field('student_id','هنرجو','text',studentsOpt()),field('date','تاریخ اولین جلسه (میلادی)','date')],async d=>{const s=db.students.find(s=>s.id===d.student_id),date=new Date(d.date+'T12:00:00Z');if(date.getUTCDay()!==Number(s.weekday))throw Error('روز انتخابی با روز ثابت هنرجو مطابقت ندارد');const rows=Array.from({length:4},(_,i)=>{const dt=new Date(date);dt.setUTCDate(dt.getUTCDate()+7*i);return {student_id:s.id,starts_at:dt.toISOString().slice(0,10)+'T'+s.class_time.slice(0,5)+':00+03:30'}});await api('/rest/v1/sessions','POST',rows)})}
async function finishSession(id,status){if(!allowed())return;try{await api('/rest/v1/sessions?id=eq.'+id,'PATCH',{status});await reload();toast('وضعیت جلسه ثبت شد')}catch(e){toast(e.message)}}
async function cancelTeacher(id){if(!allowed())return;try{const c=db.sessions.find(s=>s.id===id);await api('/rest/v1/sessions?id=eq.'+id,'PATCH',{status:'teacher_cancelled'});await api('/rest/v1/notices','POST',{student_id:c.student_id,message:'استاد در جلسه '+new Date(c.starts_at).toLocaleDateString('fa-IR')+' حضور ندارد. اعتبار محفوظ است؛ زمان جبرانی در پرتال اعلام می‌شود.'});await reload()}catch(e){toast(e.message)}}
function makeup(id){if(!allowed())return;form('تعیین جلسه جبرانی',[field('date','تاریخ جبرانی','date'),field('time','ساعت جبرانی','time')],async d=>{const c=db.sessions.find(s=>s.id===id);if(db.sessions.some(s=>s.makeup_for===id))throw Error('جبرانی این جلسه قبلاً ثبت شده');const starts=d.date+'T'+d.time+':00+03:30';await api('/rest/v1/sessions','POST',{student_id:c.student_id,starts_at:starts,makeup_for:id});await api('/rest/v1/notices','POST',{student_id:c.student_id,message:'جلسه جبرانی شما: '+new Date(starts).toLocaleString('fa-IR',{timeZone:'Asia/Tehran'})})})}
function requestAbsence(){if(demo){toast('برای درخواست غیبت وارد حساب شوید');return}const sessions=db.sessions.filter(s=>s.status==='scheduled');form('اعلام غیبت حداقل ۴ روز قبل',[field('session_id','جلسه موردنظر','text',sessions.map(s=>[s.id,new Date(s.starts_at).toLocaleString('fa-IR',{timeZone:'Asia/Tehran'})]))],d=>{const c=sessions.find(s=>s.id===d.session_id);return api('/rest/v1/absence_requests','POST',{session_id:c.id,student_id:c.student_id})})}
async function approveAbsence(id){if(!allowed())return;try{const r=db.absence_requests.find(r=>r.id===id);await api('/rest/v1/sessions?id=eq.'+r.session_id,'PATCH',{status:'excused'});await api('/rest/v1/absence_requests?id=eq.'+id,'PATCH',{status:'approved'});await reload()}catch(e){toast(e.message)}}
function showProgram(){ $('mtitle').textContent='برنامه هفتگی رشته‌ها';$('fields').innerHTML='<img class="image" src="program.webp" alt="برنامه رشته‌ها">';$('error').textContent='';$('form').onsubmit=e=>{e.preventDefault();modal.close()};modal.showModal()}
function downloadTemplate(){const data=[{first_name:'',last_name:'',father_name:'',national_id:'',mobile:'',birth_date:'2000-01-01',home_phone:'',address:'',teacher_id:db.teachers[0].id,subject:'ویولن',weekday:2,class_time:'16:00',opening_credit:0,opening_debt:0}];const a=document.createElement('a');a.href=URLcreate(data);a.download='hezardastan-import.json';a.click();setTimeout(()=>globalThis.URL.revokeObjectURL(a.href),1000)}function URLcreate(data){return globalThis.URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}))}
let importRows=[];async function previewImport(input){if(!allowed())return;try{const rows=JSON.parse(await input.files[0].text());if(!Array.isArray(rows)||!rows.length)throw Error('فایل باید آرایه غیرخالی باشد');const seen=new Set();for(const r of rows){validateStudent(r);if(seen.has(r.national_id))throw Error('کد ملی تکراری در فایل');seen.add(r.national_id)}importRows=rows;$('importpreview').textContent=money(rows.length)+' ردیف آماده بررسی نهایی. ';const b=document.createElement('button');b.textContent='تأیید و ثبت گروهی';b.onclick=async()=>{try{await api('/rest/v1/students','POST',importRows);importRows=[];await reload();toast('انتقال با موفقیت انجام شد')}catch(e){toast(e.message)}};$('importpreview').append(b)}catch(e){toast(e.message)}}
$('today').textContent=new Date().toLocaleDateString('fa-IR',{weekday:'long',day:'numeric',month:'long'});render();

function newPayroll(){if(!allowed())return;form('ثبت تسویه انجام‌شده استاد',[field('teacher_id','استاد','text',db.teachers.map(t=>[t.id,t.name])),field('amount','مبلغ / تومان','number'),field('reference','شماره پیگیری واریز')],d=>api('/rest/v1/payroll','POST',d))}

async function acceptRules(){if(demo){toast('ابتدا وارد حساب هنرجو شوید');return}try{await api('/rest/v1/rpc/accept_academy_rules','POST',{});await reload();toast('پذیرش قوانین با زمان ثبت شد')}catch(e){toast(e.message)}}
